# A synthetic pig: linear growth plus noise, with optional spikes
make_pig <- function(id = "p1", days = 70, start = 30, adg = 0.9,
                     per_day = 8, spikes = 0, location = "101", seed = 1) {
  set.seed(seed)
  t <- sort(runif(days * per_day, 0, days))
  w <- start + adg * t + rnorm(length(t), 0, 0.5)
  if (spikes > 0) {
    idx <- round(seq(10, length(t) - 10, length.out = spikes))
    w[idx] <- w[idx] + 25
  }
  et <- as.POSIXct("2024-01-01", tz = "UTC") + t * 86400
  is_spike <- seq_along(t) %in% if (spikes > 0) idx else integer()
  data.table::data.table(
    responder = id, responder_raw = id, identified = TRUE, location = location,
    date = as.Date(et), seq_days = as.integer(as.Date(et) - as.Date("2024-01-01")) + 1L,
    entry_time = et, weight = w, is_spike = is_spike
  )
}

test_that("clean_weight runs on NEDAP and FIRE with every preset", {
  for (data in list(nedap, fire)) {
    v <- prep_visits(data, verbose = 0)
    before <- data.table::copy(v)
    for (p in c("casey", "national", "legacy")) {
      w <- clean_weight(v, qc = qc_config(p), verbose = 0)
      expect_s3_class(w, c("ppt_weight", "ppt_result"))
      expect_named(w, c("per_pig", "daily", "removed", "settings", "records"))
      expect_equal(nrow(w$per_pig), length(unique(v$responder[v$identified])))
      expect_true(all(w$per_pig$status %in% c("keep", "low_confidence", "removed")))
      expect_true(all(w$daily$responder %in% w$per_pig[status != "removed", responder]))
      expect_equal(attr(w$settings, "profile"), p)
    }
    expect_identical(v, before)
  }
})

test_that("kept pigs meet every pig-level rule", {
  qc <- qc_config()
  w <- clean_weight(prep_visits(nedap, verbose = 0), verbose = 0)
  k <- w$per_pig[status != "removed"]
  expect_true(all(k$n_valid >= qc$min_records))
  expect_true(all(k$test_days >= qc$min_test_days))
  expect_true(all(k$missing_rate <= qc$max_missing_rate))
  ok_weights <- k$entry_weight <= qc$entry_weight_max & k$exit_weight >= qc$exit_weight_min
  expect_true(all(k[!ok_weights, status] == "low_confidence"))
  # the NEDAP pig with only 2 days of data is removed
  short <- w$per_pig[test_days < qc$min_test_days | n_valid < qc$min_records]
  expect_gte(nrow(short), 1L)
  expect_true(all(short$status == "removed"))
  expect_true(all(short$responder %in% w$removed$responder))
})

test_that("every outlier method finds the spikes", {
  pig <- make_pig(spikes = 6)
  spike_w <- pig$weight[pig$is_spike]
  for (m in c("rlm", "loess", "sd", "stl")) {
    # tracking off: it would already remove the spikes before the methods
    w <- clean_weight(pig, qc = qc_config(weight_outlier = m, weight_track = FALSE, adapt_days = 0),
                      verbose = 0)
    flagged <- w$records[outlier == TRUE, weight]
    expect_true(all(spike_w %in% flagged), info = m)
    expect_lt(length(flagged), 30, label = m)
    expect_true(all(grepl(m, w$records[outlier == TRUE, qc_flag])), info = m)
  }
})

test_that("majority combination is stricter than any", {
  pig <- make_pig(spikes = 6)
  any_q <- qc_config(weight_outlier = c("rlm", "loess", "sd"), outlier_combine = "any")
  maj_q <- qc_config(weight_outlier = c("rlm", "loess", "sd"), outlier_combine = "majority")
  n_any <- sum(clean_weight(pig, any_q, verbose = 0)$records$outlier)
  n_maj <- sum(clean_weight(pig, maj_q, verbose = 0)$records$outlier)
  expect_gte(n_any, n_maj)
  expect_gte(n_maj, 6)
})

test_that("weight range and optional rules flag records", {
  pig <- make_pig()
  pig$weight[c(5, 50)] <- c(5, 200)
  w <- clean_weight(pig, verbose = 0)
  expect_equal(w$records[qc_flag == "weight_range", .N], 2L)
  # daily drop: one day 20% lighter
  pig2 <- make_pig()
  d <- pig2$date[pig2$date == pig2$date[300]]
  pig2[date == d[1], weight := weight * 0.8]
  # (tracking off: it would already remove a whole day 20% lighter)
  w2 <- clean_weight(pig2, qc = qc_config(daily_drop_min = 0.9, weight_outlier = "rlm", rlm_cutoff = 0,
                                          weight_track = FALSE), verbose = 0)
  expect_true(all(w2$records[date == d[1], outlier]))
  expect_true(all(grepl("daily_drop", w2$records[date == d[1], qc_flag])))
  # relative deviation
  w3 <- clean_weight(pig, qc = qc_config(rel_dev_max = 0.25), verbose = 0)
  expect_false(any(grepl("rel_dev", w3$records$qc_flag)))
})

test_that("tracking from the end removes readings of several pigs on the scale", {
  pig <- make_pig(per_day = 12, start = 22, days = 80)
  pig[, tt := as.numeric(entry_time - min(entry_time), units = "days")]
  t <- pig$tt
  # the new pig grows slowly for 3 weeks (lag after entry), then normally
  pig[, weight := 22 + ifelse(tt < 21, 0.15 * tt, 3.15 + 0.9 * (tt - 21)) + stats::rnorm(.N, 0, 0.4)]
  # weeks 1-5: half of the readings include other small pigs (too heavy)
  set.seed(3)
  multi <- t < 35 & stats::runif(nrow(pig)) < 0.5
  pig[multi, weight := weight * stats::runif(.N, 1.25, 2.2)]
  w <- clean_weight(pig, qc_config(adapt_days = 0), verbose = 0)
  r <- w$records
  expect_gt(mean(r$outlier[multi]), 0.95)
  expect_lt(mean(r$outlier[!multi]), 0.05)        # also the slow early growth
  expect_true(all(r[multi & outlier == TRUE, qc_flag] %in% c("track", "weight_range")))
  expect_equal(w$per_pig$track_removed, mean(r$qc_flag == "track"))
  off <- clean_weight(pig, qc_config(weight_track = FALSE), verbose = 0)
  expect_true(is.na(off$per_pig$track_removed))
  # ADG of the stage is close to the true one with tracking
  a <- calc_adg(w, verbose = 0)$per_pig
  expect_equal(a$adg, 900, tolerance = 0.05)
})

test_that("a long second weight band flags the pig as a weighing fault", {
  pig <- make_pig(per_day = 12, days = 80)
  pig[, tt := as.numeric(entry_time - min(entry_time), units = "days")]
  set.seed(4)
  # a faulty scale: until day 60, 60% of the readings are 15 kg too low
  bad <- pig$tt < 60 & stats::runif(nrow(pig)) < 0.6
  pig[bad, weight := weight - 15]
  w <- clean_weight(pig, verbose = 0)
  expect_gt(mean(w$records$outlier[bad]), 0.95)
  expect_equal(w$per_pig$status, "low_confidence")
  expect_match(w$per_pig$reason, "weighing fault")
})

test_that("clean and short pigs are not changed by the tracking", {
  w <- clean_weight(make_pig(per_day = 12), verbose = 0)
  expect_lt(w$per_pig$track_removed, 0.02)
  short <- track_weight(seq(0, 5, by = 0.1), 30 + seq(0, 5, by = 0.1), 0.08)
  expect_true(all(short$keep))
  expect_true(is.na(short$removed))
  expect_error(qc_config(weight_track = "yes"), "TRUE or FALSE")
})

test_that("weights of the adaptation days are not used", {
  pig <- make_pig(per_day = 12)
  w <- clean_weight(pig, verbose = 0)
  r <- w$records
  first <- min(r$date)
  expect_true(all(r[date < first + 7, qc_flag] == "adaptation"))
  expect_true(all(r[date < first + 7, outlier]))
  expect_false(any(r[date >= first + 7, qc_flag] == "adaptation"))
  w0 <- clean_weight(pig, qc_config(adapt_days = 0), verbose = 0)
  expect_false(any(w0$records$qc_flag == "adaptation"))
})

test_that("national weight rules: whole days off the curve, weighted daily means", {
  pig <- make_pig(per_day = 12)
  d5 <- sort(unique(pig$date))[30]
  pig[date == d5, weight := weight + 1.7]        # a whole day 1.7 kg too heavy
  q <- qc_config(adapt_days = 0, weight_track = FALSE, rlm_cutoff = 0.01,
                 day_weight_min = 0.9, daily_weight = "weighted_mean")
  w <- clean_weight(pig, q, verbose = 0)
  expect_true(all(w$records[date == d5, outlier]))
  expect_true(all(w$records[date == d5, qc_flag] %in% c("day_weight", "rlm")))
  expect_true(any(w$records[date == d5, qc_flag] == "day_weight"))
  expect_equal(daily_weight_value(c(10, 20), c(1, 3), "weighted_mean"), 17.5)
  expect_equal(daily_weight_value(c(10, 20, 90), c(1, 1, 1), "median"), 20)
  expect_equal(daily_r2(1:10, 30 + 1:10), 1)
  expect_true(w$per_pig$r2_daily > 0.99)
  # feed missing and daily R2 remove pigs in the national method
  short_feed <- clean_weight(pig, qc_set(q, list(max_feed_missing = 0, daily_r2_min = 0.99999)),
                             verbose = 0)
  expect_equal(short_feed$per_pig$status, "removed")
  expect_match(short_feed$per_pig$reason, "R2 of the daily weights")
})

test_that("length rules remove pigs, entry/exit rules only flag them", {
  heavy <- make_pig("heavy", start = 80)          # entry weight too high
  light <- make_pig("light", start = 20, adg = 0.5, seed = 2)  # exit too low
  short <- make_pig("short", days = 20, seed = 3)  # test too short
  few <- make_pig("few", per_day = 0.2, seed = 4)  # too few records
  ok <- make_pig("ok", seed = 5)
  w <- clean_weight(rbind(heavy, light, short, few, ok), verbose = 0)
  st <- w$per_pig[, stats::setNames(status, responder)]
  expect_equal(unname(st[c("heavy", "light", "short", "few", "ok")]),
               c("low_confidence", "low_confidence", "removed", "removed", "keep"))
  r <- w$per_pig[, stats::setNames(reason, responder)]
  expect_match(r[["heavy"]], "entry weight")
  expect_match(r[["light"]], "exit weight")
  expect_match(r[["short"]], "test period")
  expect_match(r[["few"]], "valid weights")
  expect_setequal(w$removed$responder, c("short", "few"))
  expect_true(all(c("heavy", "light") %in% w$daily$responder))
})

test_that("curve R2 only lowers confidence", {
  pig <- make_pig()
  pig[, weight := weight + rnorm(.N, 0, 6)]
  w <- clean_weight(pig, qc = qc_config(curve_r2_min = 0.99), verbose = 0)
  expect_equal(w$per_pig$status, "low_confidence")
  expect_match(w$per_pig$reason, "R2")
  expect_equal(nrow(w$removed), 0L)
  expect_gt(nrow(w$daily), 0L)
})

test_that("a pig whose fit fails is removed, others continue", {
  pig <- make_pig()
  tiny <- make_pig("tiny")[1:3]
  w <- clean_weight(rbind(pig, tiny), qc = qc_config(min_records = 3, adapt_days = 0), verbose = 0)
  expect_equal(w$per_pig[responder == "tiny", status], "removed")
  expect_match(w$per_pig[responder == "tiny", reason], "fit failed")
  expect_equal(w$per_pig[responder == "p1", status], "keep")
})

test_that("daily weight jumps are measured and only flag pigs when asked", {
  v <- prep_visits(nedap, verbose = 0)
  w <- clean_weight(v, verbose = 0)
  expect_true("max_daily_jump" %in% names(w$per_pig))
  expect_false(any(grepl("day-to-day", w$per_pig$reason)))
  w4 <- clean_weight(v, qc = qc_config(max_daily_jump_kg = 4), verbose = 0)
  flagged <- w4$per_pig[grepl("day-to-day", reason)]
  expect_gt(nrow(flagged), 0)
  expect_true(all(flagged$status %in% c("low_confidence", "removed")))
  expect_equal(w4$per_pig[status == "removed", .N], w$per_pig[status == "removed", .N])
})

